// --- fec_country_display_name  (source lines 36-72; slices: authors)
  function fec_country_display_name($name) {
    $name = trim((string)$name);
    if ($name === '') return '';

    // If already mixed/lowercase, keep it
    if (preg_match('/[a-z]/', $name)) return $name;

    // Acronyms (USA/UAE)
    if (preg_match('/^[A-Z]{2,4}$/', $name)) return $name;

    $lower = function_exists('mb_strtolower') ? mb_strtolower($name, 'UTF-8') : strtolower($name);

    $words = preg_split('/\s+/', $lower, -1, PREG_SPLIT_NO_EMPTY);
    $out = array();

    foreach ((array)$words as $w) {
      // keep hyphen groups
      $hy = explode('-', $w);
      $hyOut = array();
      foreach ($hy as $seg) {
        if ($seg === '') { $hyOut[] = ''; continue; }

        // handle apostrophe groups
        $ap = explode("'", $seg);
        for ($i = 0; $i < count($ap); $i++) {
          if ($ap[$i] === '') continue;
          $ap[$i] = ucfirst($ap[$i]);
        }
        $seg = implode("'", $ap);

        $hyOut[] = $seg;
      }
      $out[] = implode('-', $hyOut);
    }

    return implode(' ', $out);
  }

