    // BLACKLISTED: contiene "bl" o "yes" (asterisk-list di JReviews)
    if (!empty($jr_blacklisted) && (fnmatch('*bl*', $jr_blacklisted) || fnmatch('*yes*', $jr_blacklisted))) {
      return true;
    }

